import { WEEK_DROPS_HASH, WEEK_DROP_WEEKS, loadWeekDrops } from './__generated__/week-drops-index';
import { CONTENT_OVERLAYS } from '../logic/content-locale';
import { mergeOverlaysInto } from '../logic/lessons/lesson-store';
import { createWeekDropStore } from '../logic/week-drop/drop-store';

/**
 * "This week in Korea" (F-CURR-002 §5.7, §10, row CM-48), generated by scripts/build-week-drops.mjs from
 * content/weekly/*.json: the Mondays that have a drop (so Home loads nothing in a week without one) and the store of
 * the one content-hashed chunk that holds the drops, reached through the literal `import()` of the generated index.
 * Its loads lay the drops' word meanings into `CONTENT_OVERLAYS`, where the review rounds read them.
 */
export const WEEK_DROP_WEEKS_BUILT: readonly string[] = WEEK_DROP_WEEKS;

export const weekDrops = createWeekDropStore({ hash: WEEK_DROPS_HASH, load: loadWeekDrops }, (tables) => mergeOverlaysInto(CONTENT_OVERLAYS as Parameters<typeof mergeOverlaysInto>[0], tables));
